import sys

# Increase recursion depth just in case, though iterative DP is used.
sys.setrecursionlimit(20000)

def count_distinct_prime_factors(n: int) -> int:
    if n <= 1:
        return 0
    count = 0
    d = 2
    while d * d <= n:
        if n % d == 0:
            count += 1
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        count += 1
    return count

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        S = []
        for _ in range(N):
            S.append(int(next(iterator)))
    except StopIteration:
        return

    # Precompute scores for all possible subsets (masks)
    # There are 2^N subsets. N <= 14, so 2^14 = 16384.
    num_states = 1 << N
    scores = [0] * num_states

    # Iterate over all masks
    for mask in range(1, num_states):
        total_sum = 0
        for i in range(N):
            if mask & (1 << i):
                total_sum += S[i]
        scores[mask] = count_distinct_prime_factors(total_sum)

    # DP for maximum revenue
    # dp[mask] = max revenue to sell the subset 'mask'
    dp = [-1] * num_states
    dp[0] = 0

    for mask in range(1, num_states):
        # Option 1: Treat the entire 'mask' as one customer's purchase
        current_score = scores[mask]
        if dp[mask] == -1:
            dp[mask] = current_score
        else:
            dp[mask] = max(dp[mask], current_score)

        # Option 2: Split 'mask' into a non-empty subset 'sub' and the rest 'mask ^ sub'
        # We iterate over all proper non-empty submasks of 'mask'
        # To avoid double counting and ensure efficiency, we can iterate submask from (mask-1) & mask downwards
        sub = mask
        while sub > 0:
            # sub is a non-empty subset of mask
            prev_mask = mask ^ sub
            if dp[prev_mask] != -1 and dp[sub] != -1:
                revenue = dp[prev_mask] + dp[sub]
                if revenue > dp[mask]:
                    dp[mask] = revenue

            # Move to next submask: remove the lowest set bit
            # sub = (sub - 1) & mask
            sub = (sub - 1) & mask

    print(dp[num_states - 1])

if __name__ == '__main__':
    solve()
